import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a small bonus for near-exact fits.

    Base score is -leftover (best fit). Leftovers below about 0.5% of
    capacity are almost fully packed, so they get a bonus that decays
    quickly. Larger gaps keep pure best-fit ordering.
    """
    bins = np.asarray(bins, dtype=float)
    if bins.size == 0:
        return bins.copy()
    cap = float(np.max(bins))
    if cap <= 0:
        return np.zeros_like(bins)
    left = bins - item
    rn = np.maximum(left, 0.0) / cap
    score = -left / cap
    # Narrow bonus for leftovers within ~0.5% of capacity (near-exact fits).
    score = score + 0.01 * np.exp(-(rn / 0.005) ** 2)
    return np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=-1e6)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a stronger exact-fit bonus and a smooth sliver penalty.

    Leftover fraction rn = (bin_remaining - item) / cap. Best fit ranks by -rn.
    Exact fits get a bonus. Small positive leftovers (slivers) get an
    exponentially decaying penalty so that near-empty gaps are avoided.
    """
    bins = np.asarray(bins, dtype=float)
    if bins.size == 0:
        return bins.copy()
    cap = float(np.max(bins))
    if cap <= 0:
        return np.zeros_like(bins)
    gap = bins - item
    rn = np.maximum(gap, 0.0) / cap
    exact = rn <= 1e-9
    score = -rn + 0.5 * exact
    sliver = np.exp(-rn / 0.02)
    score = score - np.where(exact, 0.0, 0.05 * sliver)
    return np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=-1e6)

import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    """Best fit with a mild, item-scaled penalty on small leftover gaps."""
    left = bins - item
    s = max(float(item), 1e-9)
    return -left - 0.3 * s * np.exp(-left / s)
